"use client";

import "./menu.css";

import {
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type KeyboardEvent,
  type MouseEvent,
  type ReactNode,
} from "react";
import { placeFromInvoker, popoverAnchorStyle, triggerAnchorStyle } from "./anchor";
import { Button, type ButtonVariant } from "./button";
import { cx } from "./cx";

export type MenuProps = ComponentProps<"div">;

export type MenuTriggerProps = {
  menu: string;
  children?: ReactNode;
  className?: string | undefined;
  variant?: ButtonVariant | undefined;
  disabled?: boolean | undefined;
};

export type MenuItemProps = {
  children?: ReactNode;
  className?: string | undefined;
  disabled?: boolean | undefined;
  onClick?: ((event: MouseEvent<HTMLButtonElement>) => void) | undefined;
};

function menuItems(root: HTMLElement | null) {
  return Array.from(
    root?.querySelectorAll<HTMLElement>('[role="menuitem"]:not([disabled])') ??
      [],
  );
}

function hidePopover(node: HTMLElement | null) {
  if (node && "hidePopover" in node) {
    (node as HTMLElement & { hidePopover: () => void }).hidePopover();
  }
}

export function Menu({ className, onKeyDown, id, style, ...rest }: MenuProps) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const onToggle = (event: Event) => {
      if (!("newState" in event) || (event as ToggleEvent).newState !== "open") {
        return;
      }
      placeFromInvoker(node);
      menuItems(node)[0]?.focus();
    };
    node.addEventListener("toggle", onToggle);
    return () => node.removeEventListener("toggle", onToggle);
  }, []);

  function move(event: KeyboardEvent<HTMLDivElement>, delta: number) {
    const list = menuItems(ref.current);
    if (list.length === 0) return;
    const current = list.indexOf(event.target as HTMLElement);
    const index = current < 0 ? 0 : (current + delta + list.length) % list.length;
    const next = list[index];
    if (!next) return;
    event.preventDefault();
    next.focus();
  }

  return (
    <div
      {...rest}
      id={id}
      ref={ref}
      popover="auto"
      role="menu"
      aria-orientation="vertical"
      className={cx("ns-popover ns-menu", className)}
      style={{ ...popoverAnchorStyle(id), ...style }}
      onKeyDown={(event) => {
        if (event.key === "ArrowDown") move(event, 1);
        else if (event.key === "ArrowUp") move(event, -1);
        else if (event.key === "Home") {
          const first = menuItems(ref.current)[0];
          if (first) {
            event.preventDefault();
            first.focus();
          }
        } else if (event.key === "End") {
          const list = menuItems(ref.current);
          const last = list[list.length - 1];
          if (last) {
            event.preventDefault();
            last.focus();
          }
        } else if (event.key === "Tab") {
          hidePopover(ref.current);
        }
        onKeyDown?.(event);
      }}
    />
  );
}

export function MenuTrigger({
  menu,
  children,
  className,
  variant = "outline",
  disabled,
}: MenuTriggerProps) {
  const [expanded, setExpanded] = useState(false);

  useEffect(() => {
    const node = document.getElementById(menu);
    if (!node) return;
    const onToggle = (event: Event) => {
      setExpanded(
        "newState" in event && (event as ToggleEvent).newState === "open",
      );
    };
    node.addEventListener("toggle", onToggle);
    setExpanded(node.matches(":popover-open"));
    return () => node.removeEventListener("toggle", onToggle);
  }, [menu]);

  return (
    <Button
      variant={variant}
      className={className}
      popoverTarget={menu}
      style={triggerAnchorStyle(menu)}
      aria-haspopup="menu"
      aria-expanded={expanded}
      aria-controls={menu}
      {...(disabled ? { disabled: true } : {})}
    >
      {children}
    </Button>
  );
}

export function MenuItem({
  children,
  className,
  disabled,
  onClick,
}: MenuItemProps) {
  return (
    <Button
      variant="ghost"
      role="menuitem"
      tabIndex={-1}
      className={cx("ns-menu__item", className)}
      {...(disabled ? { disabled: true } : {})}
      onClick={(event) => {
        onClick?.(event);
        hidePopover(event.currentTarget.closest("[popover]"));
      }}
    >
      {children}
    </Button>
  );
}

@layer components {
  .ns-popover.ns-menu {
    flex-direction: column;
    gap: var(--space-1, 0.25rem);
    padding: var(--inset-list, var(--space-2, 0.31rem));
    border-radius: var(
      --radius-list,
      calc(var(--radius, 0.4rem) + var(--space-2, 0.31rem))
    );
    background: var(--face);
    background-clip: padding-box;
    font: inherit;
    box-shadow: var(--float, 0 8px 20px rgb(0 0 0 / 12%));
  }

  .ns-popover.ns-menu:popover-open {
    display: flex;
  }

  .ns-button.ns-menu__item {
    width: 100%;
    min-height: 0;
    justify-content: flex-start;
    padding: var(--space-1, 0.25rem) var(--space-3, 0.39rem);
    border: 1px solid transparent;
    border-radius: var(--radius, 0.4rem);
    background: none;
    background-clip: padding-box;
    color: var(--text-sub, #5c5c5c);
    box-shadow: var(--flat);
  }

  .ns-button.ns-menu__item:focus,
  .ns-button.ns-menu__item:focus-visible {
    color: var(--text-heading, #111);
    border-color: transparent;
    background: var(--bg-hover, #f3f2f1);
    box-shadow: var(--flat);
  }

  .ns-button.ns-menu__item:active:not(:disabled):not([aria-disabled="true"]) {
    transform: translateY(2px);
    color: var(--text-heading, #111);
    background: var(--bg-hover, #f3f2f1);
    box-shadow: var(--flat);
  }

  @media (hover: hover) {
    .ns-button.ns-menu__item:hover:not(:disabled):not([aria-disabled="true"]) {
      color: var(--text-heading, #111);
      background: var(--bg-hover, #f3f2f1);
    }

    .ns-button.ns-menu__item:hover:focus:not(:disabled):not(
        [aria-disabled="true"]
      ) {
      border-color: transparent;
      box-shadow: var(--flat);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .ns-button.ns-menu__item:active:not(:disabled):not([aria-disabled="true"]) {
      transform: none;
    }
  }
}

import type { CSSProperties } from "react";

function ident(id: string) {
  return `--ns-${id.replace(/[^a-zA-Z0-9_-]/g, "")}`;
}

export function triggerAnchorStyle(id: string): CSSProperties {
  return { anchorName: ident(id) } as CSSProperties;
}

export function popoverAnchorStyle(id: string | undefined): CSSProperties {
  if (!id) return {};
  return { positionAnchor: ident(id) } as CSSProperties;
}

export function supportsAnchorPosition() {
  return (
    typeof CSS !== "undefined" &&
    (CSS.supports("position-area: block-end") ||
      CSS.supports("top: anchor(bottom)"))
  );
}

export function placeFromInvoker(node: HTMLElement) {
  if (!node.id || supportsAnchorPosition()) return;
  const invoker = document.querySelector(
    `[popovertarget="${CSS.escape(node.id)}"]`,
  );
  if (!(invoker instanceof HTMLElement)) return;
  const rect = invoker.getBoundingClientRect();
  node.style.top = `${Math.round(rect.bottom + 6)}px`;
  node.style.left = `${Math.round(rect.left)}px`;
}
